1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	
26	const basePremiumOf = (item: Item): number =>
27	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
28	
29	const itemModifierRateOf = (item: Item): number =>
30	  item.cursed ? CURSED_SURCHARGE_RATE : 0;
31	
32	const premiumOf = (item: Item): number =>
33	  basePremiumOf(item) * (1 + itemModifierRateOf(item));
34	
35	const sumItemPremiums = (items: Item[]): number =>
36	  items.reduce((sum, item) => sum + premiumOf(item), 0);
37	
38	const BLOCK_SIZE = 3;
39	const BLOCK_BASE_PREMIUM = 60;
40	
41	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
42	  sameTypeGroup.length === BLOCK_SIZE;
43	
44	const groupByType = (items: Item[]): Item[][] => {
45	  const groups = new Map<string, Item[]>();
46	  for (const item of items) {
47	    const group = groups.get(item.type) ?? [];
48	    group.push(item);
49	    groups.set(item.type, group);
50	  }
51	  return [...groups.values()];
52	};
53	
54	const premiumOfGroup = (sameTypeGroup: Item[]): number =>
55	  isComponentBlock(sameTypeGroup)
56	    ? BLOCK_BASE_PREMIUM
57	    : sumItemPremiums(sameTypeGroup);
58	
59	export const quote = (customer: Customer, items: Item[]): number => {
60	  const policyPremium = groupByType(items).reduce(
61	    (sum, group) => sum + premiumOfGroup(group),
62	    0,
63	  );
64	
65	  return policyPremium + PROCESSING_FEE;
66	};
67	
68	export const claim = (): number => {
69	  return undefined as unknown as number;
70	};
